ALTER TABLE public.ech_listing_reviews DROP CONSTRAINT IF EXISTS ech_review_pending_commercial_values;
ALTER TABLE public.ech_listing_reviews ADD CONSTRAINT ech_review_pending_commercial_values CHECK ((((unit_cost IS NOT NULL) AND (target_price IS NOT NULL)) OR ((review_status = 'awaiting_lee_approval'::text) AND (sku = ANY (ARRAY['BOSE-ACOUSTIMASS10-V-O2'::text, 'EPSON-PROCINEMA6050-O2'::text, 'KR26-UBI-US-8-150W-O2'::text, 'KR26-UBI-UCK-G2-O2'::text, 'KR26-UBI-UCK-G2-PLUS-O2'::text, 'KR26-UBI-US-24-O2'::text, 'KR26-UBI-USW-LITE-16-POE-O2'::text, 'KR26-UBI-USG-O2'::text, 'KR26-UBI-USG-PRO-4-O2'::text, 'KR26-UBI-US-8-60W-O2'::text, 'KR26-ARAK-AN-320-AP-I-O2'::text, 'KR26-ARAK-AN-210-SW-R-8-POE-O2'::text, 'KR26-ARAK-AN-300-SW-R-8-POE-O2'::text, 'KR26-ARAK-AN-310-SW-R-8-O2'::text, 'KR26-ARAK-AN-110-RT-2L1W-O2'::text, 'KR26-TPL-TL-SG1210MP-O2'::text, 'KR26-TPL-EAP650-N1'::text, 'KR26-DC-DC-S-24M-O2'::text, 'KR26-ULTRA-28-PORT-SWITCH-O2'::text]))) OR (review_status = ANY (ARRAY['returned_to_paige'::text, 'rejected'::text])) OR ((review_status = 'awaiting_lee_approval'::text) AND (sku = ANY (ARRAY['INT26-C4-SR260'::text, 'INT26-AVPRO-AC-MXNET-SW10'::text, 'INT26-NETGEAR-GS348PP'::text, 'INT26-EPISODE-ESS-SUB-SNGL-8'::text, 'INT26-KEF-T301C'::text, 'INT26-KEF-CI200QL-GRILLE-WH'::text, 'INT26-KEF-RIF200R'::text, 'INT26-KEF-Q6-META-GRILLE'::text, 'INT26-KEF-CI200QR-GRILLE-WH'::text]))) OR ((review_status = 'awaiting_lee_approval'::text) AND private.ech_pending_commercial_allowed_v28(queue_id, sku))));
